#!/usr/bin/env node
/**
 * Regression check for the desktop Rust-test resource contract: every path
 * that tauri-build validates or generate_context! reads must exist in a
 * clean checkout BEFORE cargo test compiles. Fails with an actionable list
 * instead of a proc-macro panic inside CI.
 *
 * Expected in a clean tree:
 *   - icons/icon.png    generated by scripts/desktop-icon.mjs (gitignored)
 *   - icons/icon.icns   committed source asset
 *   - resources/sidecar/dsh-desktop-runtime (dev-profile placeholder)
 *   - resources/runtime/cordis.yml          (runtime config copy)
 */

import { existsSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repo = resolve(fileURLToPath(new URL('.', import.meta.url)), '..')
const tauri = process.env.DSH_TAURI_ROOT !== undefined && process.env.DSH_TAURI_ROOT !== ''
  ? resolve(process.env.DSH_TAURI_ROOT)
  : resolve(repo, 'apps/desktop/src-tauri')
const conf = JSON.parse(readFileSync(resolve(tauri, 'tauri.conf.json'), 'utf8'))

const required = []
for (const icon of conf.bundle?.icon ?? []) {
  required.push([icon, 'tauri.conf.json bundle.icon'])
}
// generate_context! reads a square icon.png next to the configured icons.
required.push(['icons/icon.png', 'tauri generate_context! reads icon.png'])
for (const resource of Object.keys(conf.bundle?.resources ?? {})) {
  required.push([resource, 'tauri-build declared bundle resource'])
}

const missing = required.filter(([rel]) => !existsSync(resolve(tauri, rel)))
if (missing.length > 0) {
  console.error('check-desktop-rust-resources: FAILED — cargo test would panic on:')
  for (const [rel, why] of missing) console.error('  ' + rel + ' (' + why + ')')
  console.error('Run scripts/prepare-desktop-rust-tests.mjs first (or node scripts/desktop-icon.mjs for the icon).')
  process.exit(1)
}
console.log('check-desktop-rust-resources: all cargo-test resources present')
